const signals =
$('Merge Scout Memory').first().json.qualification_signals || {};

const scoutFields = [
  'trigger_event',
  'visible_problem',
  'goal',
  'stakes',
  'emotional_driver',
  'cost_of_inaction',
  'past_attempts',
  'investment_history',
  'desired_state',
  'readiness'
];

let completed = 0;

for (const field of scoutFields) {
  if (
    signals[field] !== null &&
    signals[field] !== undefined &&
    signals[field] !== ''
  ) {
    completed++;
  }
}

const depthScore = Math.round(
  (completed / scoutFields.length) * 100
);

return [
  {
    json: {
      qualification_signals: signals,
      completed_fields: completed,
      total_fields: scoutFields.length,
      depth_score: depthScore
    }
  }
];

const raw = $('Scout Signal Extractor').first().json.output;

const parsed = JSON.parse(raw);

return [
  {
    json: parsed
  }
];

const currentSignals =
$('Client State Loader').first().json.qualification_signals || {};

const extracted =
$('Parse Scout Signals').first().json.new_signals || {};

const merged = { ...currentSignals };

for (const [key, value] of Object.entries(extracted)) {
  if (value !== null) {
    merged[key] = value;
  }
}

return [
  {
    json: {
      qualification_signals: merged
    }
  }
];

const signals =
$('Merge Scout Memory').first().json.qualification_signals || {};

const scoutFields = [
  'trigger_event',
  'visible_problem',
  'goal',
  'stakes',
  'emotional_driver',
  'cost_of_inaction',
  'past_attempts',
  'investment_history',
  'desired_state',
  'readiness'
];

let nextObjective = null;

for (const field of scoutFields) {
  if (
    signals[field] === null ||
    signals[field] === undefined ||
    signals[field] === ''
  ) {
    nextObjective = field;
    break;
  }
}

return [
  {
    json: {
      next_objective: nextObjective,
      qualification_signals: signals
    }
  }
];

const memory =
$('Merge Scout Memory').first().json.qualification_signals;

return [
  {
    json: {
      qualification_signals: memory
    }
  }
];

const depth =
$('Depth Calculator').first().json.depth_score;

const completed =
$('Depth Calculator').first().json.completed_fields;

let scout_complete = false;

if (depth >= 80) {
  scout_complete = true;
}

if (completed >= 8) {
  scout_complete = true;
}

return [
  {
    json: {
      ...$('Depth Calculator').first().json,
      scout_complete
    }
  }
];

